const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={verbatim:'원문 전사',excerpt:'원문 발췌',summary:'답변 요약',reconstructed:'교육용 재구성',unavailable:'본문 표시 없음'};
export const conversationTabs=[['dialogue','대화 기록'],['review','해설·시행착오'],['exercise','따라 하기'],['context','프로젝트 맥락'],['assets','관련 자료']];
export const conversationLink=(pid,eid)=>`#/conversations/${pid}${eid?'/'+eid:''}`;
export function resolveConversation(bundle,{node,projectId,episodeId}={}){
 const availableProjects=bundle.projects.filter(p=>!node||p.episodes.some(e=>e.map_nodes.includes(node)));
 if(!availableProjects.length)return null;
 const preferred=node?bundle.preferredNodes[node]:null;
 const project=availableProjects.find(p=>p.id===projectId)||availableProjects.find(p=>p.id===preferred?.[0])||availableProjects[0];
 const episodes=project.episodes.filter(e=>!node||e.map_nodes.includes(node));
 const episode=episodes.find(e=>e.id===episodeId)||episodes.find(e=>project.id===preferred?.[0]&&e.id===preferred?.[1])||episodes[0];
 const messages=episode.message_refs.map(id=>project.messages.find(m=>m.id===id));
 return {availableProjects,project,episodes,episode,messages};
}
export function relatedConversationCount(bundle,node){return bundle.projects.reduce((n,p)=>n+p.episodes.filter(e=>e.map_nodes.includes(node)).length,0);}
export function conversationIndex(bundle){
 return `<div class="conversation-intro"><div><div class="eyebrow">FROM REAL PROJECTS</div><h1 class="page-title">실제 대화로 배우기</h1><p class="page-description">어떤 문제에서 출발했는지, AI에게 무엇을 요청했는지,<br>어디서 막혔고 어떻게 요구를 고쳤는지 따라가 보세요.</p></div><a class="btn" href="#/map/core">구성도에서 찾아보기 ↗</a></div><div class="conversation-stats"><span><strong>${bundle.totals.projects}</strong>개 프로젝트</span><span><strong>${bundle.totals.episodes}</strong>개 학습 에피소드</span><span><strong>${bundle.totals.messages}</strong>개 대화 항목</span></div><p class="conversation-provenance">확보된 범위의 기록입니다. 원문 전사 ${bundle.totals.verbatim}개 · 발췌 ${bundle.totals.excerpt}개 · 요약 ${bundle.totals.summary}개 · 본문 없음 안내 ${bundle.totals.unavailable||0}개이며, 원문이 없는 답변을 새로 만들지 않았습니다. 사용자 요청과 AI 응답은 의미를 유지하여 교육용 문장으로 다듬었습니다. AI 응답의 원문·발췌·요약 구분은 그대로 표시합니다.</p><div class="conversation-project-grid">${bundle.projects.map((p,i)=>`<article class="conversation-project-card"><div class="conversation-project-meta"><span>PROJECT ${String(i+1).padStart(2,'0')}</span><span>${p.counts.episodes}개 에피소드</span></div><h2><a href="${conversationLink(p.id)}">${esc(p.shortTitle)}</a></h2><p>${esc(p.purpose)}</p><div class="conversation-project-turn"><strong>이 과정의 전환점</strong><p>${esc(p.turningPoint)}</p></div><p class="conversation-card-coverage">${esc(p.coverageNote)}</p><a class="text-link" href="${conversationLink(p.id)}">프로젝트 대화 읽기 <span aria-hidden="true">↗</span></a></article>`).join('')}</div>`;
}
// Reveal complete request/response turns, never only the progress before a final reply.
export function conversationVisibleCount(messages,requested=4){
 let count=Math.min(messages.length,Math.max(1,requested));
 while(count<messages.length&&messages[count].role==='assistant')count++;
 return count;
}
function dateLabel(value){
 if(!value)return '시각 미확인';
 const date=new Date(value);if(Number.isNaN(date.getTime()))return '시각 미확인';
 return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(date)+' KST';
}
function imageAsset(a){return `<figure class="conversation-image"><button class="image-zoom" data-image="${esc(a.publicPath)}" aria-label="${esc(a.description)} 크게 보기"><img src="${esc(a.publicPath)}" alt="${esc(a.description)}" loading="lazy"></button><figcaption>${esc(a.description)} <span>· ${esc(a.id)}</span></figcaption></figure>`;}
function plainSnippet(md){return md.replace(/[^]*/g,'').replace(/!\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/[#*`>|]/g,'').replace(/\s+/g,' ').trim().slice(0,280);}
function messageCard(project,message){
 const m=message,imgs=project.assets.filter(a=>m.asset_ids.includes(a.id)&&a.kind==='image'&&a.publicPath);
 if(m.content_type==='unavailable')return `<aside class="conversation-missing-response" id="message-${esc(project.id)}-${esc(m.id)}" tabindex="-1" aria-label="AI 응답 확보 상태 안내"><strong>이 위치에는 AI 답변 본문이 표시되지 않습니다.</strong><p>공유 화면의 대화 ${m.pair_number}을 직접 확인했지만 답변 본문은 보이지 않았습니다. 내용을 추정해 채우지 않았습니다.</p><span>${m.visible_status_text?`당시 화면 표시: ${esc(m.visible_status_text)}`:'당시 화면에 처리 문구도 표시되지 않았습니다.'}</span></aside>`;
 const edited=Boolean(m.editorial_markdown),text=m.editorial_markdown??m.content_markdown,html=m.editorialHtml??m.html;
 const files=project.assets.filter(a=>m.asset_ids.includes(a.id)&&a.kind!=='image'&&a.publicPath&&m.content_markdown.includes(a.original_filename||'\u0000')).filter((a,i,list)=>list.findIndex(b=>b.publicPath===a.publicPath)===i);
 const fileLinks=files.length?`<div class="conversation-message-files" aria-label="대화의 첨부파일"><strong>첨부파일</strong>${files.map(a=>`<a class="btn small" href="${esc(a.publicPath)}" download="${esc(a.original_filename)}">${esc(a.original_filename)} ↓</a>`).join('')}</div>`:'';
 const progress=m.role==='assistant'&&m.delivery_kind==='progress';
 const long=text.length>1800&&!progress;
 const body=!text.trim()?'<p class="chat-empty-note">텍스트 없이 전달된 항목입니다. 연결된 첨부 자료를 확인해 주세요.</p>':long?`<details class="transcript-long" ${m.role==='assistant'?'open':''} id="long-${esc(project.id)}-${esc(m.id)}"><summary><span class="transcript-preview">${esc(plainSnippet(text))}…</span><span class="transcript-open-label">대화 전문 펼치기 ↓</span></summary><div class="prose conversation-prose">${html}</div></details>`:`<div class="prose conversation-prose">${html}</div>`;
 const copyButton=()=>`<button class="text-link" data-chat-copy="${esc(m.id)}" data-project-id="${esc(project.id)}" aria-label="${esc(m.id)} ${edited?'교육용 문장':types[m.content_type]} 복사">${edited?'교육용 문장 복사':'본문 복사'}</button>`;
 if(progress)return `<details class="conversation-progress" id="message-${esc(project.id)}-${esc(m.id)}" tabindex="-1"><summary><span>AI 진행 안내</span><span class="progress-preview">${esc(plainSnippet(text).slice(0,90))}${text.length>90?'…':''}</span></summary><div class="progress-content">${body}${fileLinks}${imgs.map(imageAsset).join('')}<div class="chat-message-foot"><span class="caption">${esc(m.id)} · ${esc(m.source_locator)}</span>${text.trim()?copyButton():''}</div></div></details>`;
 return `<article class="chat-message ${m.role==='user'?'from-user':'from-assistant'} ${m.content_type==='summary'||m.content_type==='reconstructed'?'is-summary':''}" id="message-${esc(project.id)}-${esc(m.id)}" tabindex="-1"><div class="chat-avatar" aria-hidden="true">${m.role==='user'?'요청':'AI'}</div><div class="chat-message-main"><div class="chat-message-meta"><strong>${m.role==='user'?'사용자 요청':m.delivery_kind==='progress'?'AI 진행 안내':'AI 응답'}</strong><span class="transcript-type ${'type-'+esc(m.content_type)+(edited?' type-editorial':'')}">${edited?(m.role==='assistant'?types[m.content_type]+' · 경어체 편집':'교육용 문장'):types[m.content_type]}</span>${m.redacted?'<span class="transcript-type">일부 마스킹</span>':''}<span class="chat-date">${dateLabel(m.timestamp)}</span></div><div class="chat-bubble">${body}${fileLinks}${imgs.length?`<div class="conversation-message-images">${imgs.map(imageAsset).join('')}</div>`:''}</div><div class="chat-message-foot"><details class="message-source" id="source-${esc(project.id)}-${esc(m.id)}"><summary>출처 · ${esc(m.id)}</summary><p>${esc(m.source_locator)}</p>${m.capture_notes?.length?`<p>${m.capture_notes.map(esc).join('<br>')}</p>`:''}<p>자체 발화 ID · 확보 순서 ${m.sequence} · ${types[m.content_type]}</p></details>${text.trim()?copyButton():''}</div></div></article>`;
}
function assetsPane(project,episode){
 const related=episode.asset_ids.map(id=>project.assets.find(a=>a.id===id));
 return `<div class="conversation-pane-content"><h3>이 에피소드의 근거 자료</h3><p>대화 및 해설에 연결된 자료입니다. 후속 산출물도 포함하므로 모든 파일이 당시 메시지에 직접 첨부되었다는 뜻은 아닙니다.</p><div class="conversation-assets">${related.map(a=>`<article class="conversation-asset"><div class="conversation-asset-heading"><h4>${esc(a.original_filename||a.id)}</h4><span class="transcript-type">${a.availability==='included'?'파일 확보':a.distribution_status==='excluded_sensitive'?'배포 제외':'원본 미확보'}</span></div><p>${esc(a.description)}</p>${a.exclusion_reason?`<p class="caption">${esc(a.exclusion_reason)}</p>`:''}${a.kind==='image'&&a.publicPath?imageAsset(a):a.publicPath?`<a class="btn small" href="${esc(a.publicPath)}" download="${esc(a.original_filename||a.id)}">파일 받기</a>`:a.availability==='included'?`<details class="message-source"><summary>전체 프로젝트 ZIP에서 파일 찾기</summary><code>${esc((project.assetSourcePath?project.assetSourcePath+'/':project.sourcePath)+a.path)}</code></details>`:'<p class="caption">현재 배포본에 연결된 다운로드 파일은 없습니다. 위 확보 상태와 사유를 확인해 주세요.</p>'}</article>`).join('')||'<p>연결된 첨부 파일이 없습니다.</p>'}</div><h3>프로젝트 교육 자료 받기</h3><div class="conversation-downloads">${[['01_PROJECT_CONTEXT.md','프로젝트 맥락 MD'],['02_LEARNING_GUIDE.md','전체 학습 가이드 MD'],['conversation-data.json','추출 원문 JSON'],['AI_RESPONSES_FULL.md','확보한 대화 전문'],['MISSING_RESPONSES.md','미확보 답변 목록'],['CHANGELOG.md','이번 보완 내역']].filter(([f])=>project.documents[f]).map(([f,t])=>`<a class="btn small" href="${project.documents[f]}" download>${t} ↓</a>`).join('')}</div><p class="caption">추출 원문의 상대경로 파일은 전체 프로젝트 ZIP의 해당 sources 폴더에 보존되어 있습니다.</p></div>`;
}
function contextPane(project){return `<div class="conversation-pane-content"><div class="project-context-summary"><h3>왜 시작했고, 무엇이 달라졌나요?</h3><dl><dt>출발점</dt><dd>${esc(project.purpose)}</dd><dt>당시 환경</dt><dd>${esc(project.environment)}</dd><dt>방향을 바꾼 계기</dt><dd>${esc(project.turningPoint)}</dd><dt>현재 확인 범위</dt><dd>${esc(project.currentState)}</dd></dl></div><div class="conversation-supplement"><strong>포털에서 함께 볼 자료</strong><p>${esc(project.integrationNote)}</p><a class="text-link" href="#/learn/${project.supplementLesson}">관련 교육 과정 보기 ↗</a></div><details class="conversation-source-context"><summary>추출본의 프로젝트 맥락 전문 읽기</summary><div class="prose conversation-prose">${project.contextHtml}</div></details><details class="conversation-source-context"><summary>대화 확보 범위와 빠진 자료</summary><p>${esc(project.coverage.description)}</p><ul>${project.coverage.missing.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details><a class="btn small" href="${project.documents['01_PROJECT_CONTEXT.md']}" download>맥락 MD 받기 ↓</a></div>`;}
export function conversationWorkspace(bundle,state={}){
 const selection=resolveConversation(bundle,state);if(!selection)return '<div class="empty-state">이 요소에 연결된 대화가 없습니다.</div>';
 const {availableProjects,project,episodes,episode,messages}=selection;
 const tab=conversationTabs.some(([t])=>t===state.tab)?state.tab:'dialogue';
 const count=conversationVisibleCount(messages,state.visible||4);
 let pane;
 if(tab==='review')pane=`<div class="conversation-pane-content"><div class="editorial-label">교육 해설 · 당시 AI 답변과 구분</div><div class="prose conversation-prose">${episode.commentaryHtml}</div><section class="conversation-outcome"><h3>이 단계에서 확인된 결과</h3><div class="prose conversation-prose">${episode.outcomeHtml}</div></section></div>`;
 else if(tab==='exercise')pane=`<div class="conversation-pane-content"><div class="editorial-label">내 업무에 적용하기 · 교육용 재작성</div><p>아래 지시는 당시 대화를 바탕으로 정리한 실습용입니다. 실제 실행 여부와 확인 결과는 따로 기록하세요.</p><div class="prose conversation-prose">${episode.exerciseHtml}</div><div class="conversation-exercise-actions"><button class="btn primary" data-exercise-copy>실습 내용 복사</button><button class="btn" data-conversation-tab="review">결과·확인 범위 다시 보기</button></div></div>`;
 else if(tab==='context')pane=contextPane(project);
 else if(tab==='assets')pane=assetsPane(project,episode);
 else pane=`<div class="conversation-dialogue-intro"><p>당시의 요청과 응답을 확보된 순서대로 보여줍니다. 사용자 요청은 자연스러운 ‘주세요’ 체로, AI 응답의 구어체·단답형 설명은 ‘입니다/하겠습니다’ 체로 다듬었습니다. 최종 답변은 전문을 펼쳐 보여주며, 작업 중 진행 안내는 접어서 구분합니다. 코드·표·구성도와 확보된 첨부를 함께 확인할 수 있습니다. 답변의 현재 유효성과 수정 이유는 <button class="text-link" data-conversation-tab="review">해설·시행착오</button>에서 확인하세요.</p>${!messages.some(m=>m.role==='assistant')?'<p class="conversation-gap">이 에피소드에 대응하는 당시 AI 답변 원문은 확보하지 못했습니다. 아래에는 사용자 요청을 보존하고, AI 대응의 근거는 교육 해설에서 별도로 설명합니다.</p>':''}</div><div class="conversation-transcript">${messages.slice(0,count).map(m=>messageCard(project,m)).join('')}</div><div class="conversation-reveal"><span>${count} / ${messages.length}개 항목</span>${count<messages.length?`<button class="btn primary" data-conversation-more>다음 대화 보기 ↓</button><button class="btn" data-conversation-all>전체 대화 펼치기</button>`:'<button class="btn primary" data-conversation-tab="review">이 대화의 시행착오 읽기 →</button>'}</div>`;
 const selectedIndex=episodes.indexOf(episode),next=episodes[selectedIndex+1],prev=episodes[selectedIndex-1];
 const mainEpisodes=episodes.filter(e=>!e.isMeta),metaEpisodes=episodes.filter(e=>e.isMeta);
 const episodeButtons=list=>list.map(e=>`<button class="conversation-episode ${e.id===episode.id?'active':''}" data-conversation-episode="${esc(e.id)}" aria-pressed="${e.id===episode.id}"><span>${String(e.order).padStart(2,'0')}</span><span>${esc(e.title)}</span></button>`).join('');
 return `<div class="conversation-workspace" data-conversation-project="${esc(project.id)}" data-conversation-current="${esc(episode.id)}"><div class="conversation-workspace-header"><div><div class="eyebrow">PROJECT CONVERSATIONS</div><h2 id="conversation-heading" tabindex="-1">${state.nodeLabel?esc(state.nodeLabel)+' · 관련 대화':'프로젝트의 실제 대화'}</h2><p>${state.node?'선택한 요소와 연결된 에피소드만 모았습니다.':'프로젝트의 시작부터 수정·검증 과정까지 순서대로 읽어 보세요.'}</p></div><label class="conversation-project-select" for="conversation-project-select">프로젝트 선택<select id="conversation-project-select" data-conversation-select>${availableProjects.map(p=>`<option value="${esc(p.id)}" ${p.id===project.id?'selected':''}>${esc(p.shortTitle)} · ${p.episodes.filter(e=>!state.node||e.map_nodes.includes(state.node)).length}개</option>`).join('')}</select></label></div><div class="conversation-project-brief"><strong>${esc(project.shortTitle)}</strong><p>${esc(project.purpose)}</p><div class="conversation-brief-state">${esc(project.currentState)}</div>${project.supplementEpisode?`<p class="conversation-update"><a class="text-link" href="${conversationLink(project.id,project.supplementEpisode)}">${esc(project.supplementLabel||'이번에 보완된 자료 추출 대화 읽기')} ↗</a></p>`:''}<details class="conversation-coverage"><summary>대화 확보 범위 · ${esc(project.coverageNote)}</summary><p>${esc(project.coverage.description)}</p></details></div><div class="conversation-layout"><aside class="conversation-episode-list" aria-label="학습 에피소드"><div class="conversation-list-label">학습 흐름 <span>${episodes.length}개</span></div>${episodeButtons(mainEpisodes)}${metaEpisodes.length?`<details class="conversation-meta-episodes" ${episode.isMeta?'open':''}><summary>자료 추출·정리 과정 <span>${metaEpisodes.length}개</span></summary>${episodeButtons(metaEpisodes)}</details>`:''}${state.node?`<a class="conversation-full-project" href="${conversationLink(project.id,episode.id)}">이 프로젝트 전체 흐름 보기 ↗</a>`:''}</aside><section class="conversation-reader" aria-labelledby="conversation-episode-title"><header class="conversation-episode-header"><div class="eyebrow">EPISODE ${String(episode.order).padStart(2,'0')} · ${messages.length}개 대화 항목</div><h3 id="conversation-episode-title" tabindex="-1">${esc(episode.title)}</h3><p>${esc(episode.goal)}</p><details class="conversation-prerequisites"><summary>시작 전 알아둘 맥락과 준비물</summary><ul>${episode.prerequisites.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></header><div class="conversation-tabs" role="group" aria-label="에피소드 내용 선택">${conversationTabs.map(([key,label])=>`<button data-conversation-tab="${key}" class="${key===tab?'active':''}" aria-pressed="${key===tab}" aria-controls="conversation-pane">${label}</button>`).join('')}</div><div id="conversation-pane" class="conversation-pane" tabindex="-1" aria-label="${conversationTabs.find(([t])=>t===tab)[1]}">${pane}</div><nav class="conversation-pager" aria-label="이전 다음 에피소드">${prev?`<button class="pager-card pager-prev" data-conversation-episode="${esc(prev.id)}"><span class="pager-label">← 이전 에피소드</span><strong>${esc(prev.title)}</strong></button>`:'<span></span>'}${next?`<button class="pager-card pager-next" data-conversation-episode="${esc(next.id)}"><span class="pager-label">다음 에피소드 →</span><strong>${esc(next.title)}</strong></button>`:`<a class="pager-card pager-next" href="${project.documents['02_LEARNING_GUIDE.md']}" download><span class="pager-label">학습 가이드 다운로드 ↓</span><strong>프로젝트 전체 흐름 다시 보기</strong></a>`}</nav></section></div></div>`;
}
export function conversationSearchEntries(bundle){return bundle.projects.flatMap(p=>p.episodes.map(e=>({title:e.title,group:p.shortTitle,url:conversationLink(p.id,e.id),text:[e.goal,e.commentary_markdown,e.exercise_markdown,...e.message_refs.flatMap(id=>{const m=p.messages.find(m=>m.id===id);return [m.editorial_markdown??m.content_markdown];})].join('\n')})));}
